import React, { useMemo, useState } from 'react';
import { TrendingUp, Users, DollarSign, Activity, Target, Zap, CheckCircle2, Sparkles, ArrowUpRight, Filter } from 'lucide-react';

const KPIS = [
  { label: 'Total Revenue', value: '$128,430', delta: '+18.2%', icon: DollarSign, color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/20' },
  { label: 'Active Users', value: '8,412', delta: '+9.4%', icon: Users, color: 'text-blue-400', bg: 'bg-gray-500/10 border-gray-500/20' },
  { label: 'Conversion Rate', value: '4.86%', delta: '+1.2%', icon: Target, color: 'text-gray-600', bg: 'bg-gray-500/10 border-gray-500/20' },
  { label: 'Avg. Session', value: '6m 42s', delta: '+0.8%', icon: Activity, color: 'text-amber-400', bg: 'bg-amber-500/10 border-amber-500/20' },
];

const SERIES = [
  { label: 'Mon', revenue: 12400, users: 820 },
  { label: 'Tue', revenue: 15800, users: 940 },
  { label: 'Wed', revenue: 14200, users: 880 },
  { label: 'Thu', revenue: 18600, users: 1120 },
  { label: 'Fri', revenue: 21400, users: 1290 },
  { label: 'Sat', revenue: 16800, users: 1010 },
  { label: 'Sun', revenue: 23400, users: 1380 },
];

const CHANNELS = [
  { name: 'Organic Search', share: 42, color: '#8b5cf6' },
  { name: 'Direct', share: 26, color: '#06b6d4' },
  { name: 'Referral', share: 18, color: '#f59e0b' },
  { name: 'Social', share: 14, color: '#10b981' },
];

export default function App() {
  const [range, setRange] = useState('7d');
  const maxRevenue = Math.max(...SERIES.map(s => s.revenue));
  const total = CHANNELS.reduce((a, c) => a + c.share, 0);
  let acc = 0;
  const arcs = CHANNELS.map(c => {
    const start = acc; acc += c.share; return { ...c, start };
  });

  return (
    <div className="min-h-screen bg-gray-900 text-gray-600 p-6 md:p-10 selection:bg-gray-500/30">
      <header className="max-w-7xl mx-auto flex items-center justify-between mb-8 pb-4 border-b border-gray-200">
        <div className="flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-gradient-to-br from-gray-700 to-gray-800 shadow-lg shadow-gray-500/20">
            <Zap className="w-5 h-5 text-gray-600" />
          </div>
          <div>
            <h1 className="text-xl font-extrabold text-gray-600">EmployeeManagement Analytics</h1>
            <p className="text-xs text-gray-600">Real-time business intelligence</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {['24h', '7d', '30d', '90d'].map(r => (
            <button key={r} onClick={() => setRange(r)}
              className={`px-3.5 py-1.5 rounded-lg text-xs font-bold transition-all ${
                range === r ? 'bg-gray-600 text-gray-600 shadow-md shadow-gray-600/30' : 'bg-gray-100 text-gray-600 hover:bg-gray-100'
              }`}>{r}</button>
          ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto space-y-8">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
          {KPIS.map(kpi => (
            <div key={kpi.label} className="backdrop-blur-xl bg-white/[0.03] border border-gray-200 rounded-2xl p-5 hover:border-gray-200 transition-colors">
              <div className="flex items-center justify-between">
                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wider">{kpi.label}</span>
                <div className={`p-1.5 rounded-lg border {kpi.bg}`}><kpi.icon className={`w-4 h-4 {kpi.color}`} /></div>
              </div>
              <p className="text-2xl font-extrabold text-gray-600 mt-3">{kpi.value}</p>
              <span className="text-xs text-emerald-400 flex items-center gap-1 mt-1.5">
                <TrendingUp className="w-3 h-3" /> {kpi.delta} vs prev
              </span>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 backdrop-blur-xl bg-white/[0.03] border border-gray-200 rounded-2xl p-6 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-bold text-gray-600">Revenue Trend ({range})</h2>
              <span className="text-xs text-emerald-400 flex items-center gap-1"><ArrowUpRight className="w-3.5 h-3.5" /> +18.2% growth</span>
            </div>
            <div className="flex items-end gap-3 h-48">
              {SERIES.map(s => (
                <div key={s.label} className="flex-1 flex flex-col items-center gap-2 group">
                  <span className="text-[10px] text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity">${s.revenue.toLocaleString()}</span>
                  <div className="w-full rounded-t-lg bg-gradient-to-t from-gray-600/60 to-gray-400/80 hover:from-gray-500 hover:to-gray-300 transition-all"
                    style={{ height: `\${Math.round((s.revenue / maxRevenue) * 100)}%` }} />
                  <span className="text-[10px] text-gray-500 font-semibold">{s.label}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="backdrop-blur-xl bg-white/[0.03] border border-gray-200 rounded-2xl p-6 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
            <h2 className="font-bold text-gray-600 mb-6">Traffic Sources</h2>
            <div className="flex justify-center mb-6">
              <svg viewBox="0 0 42 42" className="w-40 h-40 -rotate-90">
                {arcs.map(a => (
                  <circle key={a.name} cx="21" cy="21" r="15.9" fill="none" stroke={a.color}
                    strokeWidth="6" strokeDasharray={`${a.share / total * 100} ${100 - a.share / total * 100}`}
                    strokeDashoffset={`${-a.start / total * 100}`} />
                ))}
              </svg>
            </div>
            <div className="space-y-2.5">
              {CHANNELS.map(c => (
                <div key={c.name} className="flex items-center justify-between text-xs">
                  <span className="flex items-center gap-2 text-gray-600">
                    <span className="w-2.5 h-2.5 rounded-sm" style={{ background: c.color }} />{c.name}
                  </span>
                  <span className="font-bold text-gray-600">{c.share}%</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default function Dashboard() {
  return (
    <section id="dashboard" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-gray-700">
        <h2 className="text-3xl font-bold mb-4">Dashboard</h2>
      </div>
    </section>
  );
}

export default function Orders() {
  return (
    <section id="orders" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-gray-700">
        <h2 className="text-3xl font-bold mb-4">Orders</h2>
      </div>
    </section>
  );
}

export default function Products() {
  return (
    <section id="products" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-gray-700">
        <h2 className="text-3xl font-bold mb-4">Products</h2>
      </div>
    </section>
  );
}

export default function Suppliers() {
  return (
    <section id="suppliers" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-gray-700">
        <h2 className="text-3xl font-bold mb-4">Suppliers</h2>
      </div>
    </section>
  );
}

